from pathlib import Path
import subprocess,datetime,shlex,re,json,argparse
parser=argparse.ArgumentParser()
parser.add_argument('--sprefa',type=Path,default=Path(__file__).resolve().parents[2]/'sprefa-wt/sqlite-perf-main')
args=parser.parse_args()
roots={'sprefa':args.sprefa.resolve(),'sqlite_ivm':Path(__file__).resolve().parents[1]}
rows=[]
def add(repo,source,folder,command,tests,output,kind,receipt=None):
 root=roots[repo]
 stamp=subprocess.check_output(['git','log','-1','--format=%ct','HEAD','--',source],cwd=root,text=True).strip()
 now=datetime.datetime.now().timestamp()
 def age(ts):
  if not ts:return 'uncommitted'
  seconds=max(0,int(now-int(ts)))
  return str(seconds//86400)+' days ago' if seconds>=86400 else str(seconds//3600)+' hours ago' if seconds>=3600 else str(seconds//60)+' minutes ago'
 updated=age(stamp)
 if receipt and (root/receipt).exists():
  t=subprocess.check_output(['git','log','-1','--format=%ct','HEAD','--',receipt],cwd=root,text=True).strip()
  output+='; [receipt]('+str(root/receipt)+') ('+age(t)+')'
 rows.append({'repo':repo+'@main','command':'cd '+shlex.quote(str(root/folder))+' && '+command if command else '—','tests':tests,'output':output,'updated':updated,'class':kind,'source':source,'timestamp':int(stamp or now)})
S='sprefa';Q='sqlite_ivm'
add(S,'v6/labs/exec_shootout/dl6/incbench.ts','v6','just dl6-dred-bench','45×45 grid; edge insertion, redundant/structural deletion, empty tick','Recorded insertion 2019→42 ms; deletion 3907→56 ms; empty 1926→1 ms','Incremental recursive maintenance','v6/labs/exec_shootout/dl6/FACTS.dredland.md')
add(S,'v6/sprefa-store/bench/run.sh','v6','just bench','Layered DAG/cyclic retractions; isolated engine processes; hash oracle','Recorded DAG 960k: count 429.6 ms; DRed 1774.6 ms; DD 174.6 ms','Retraction strategies, durability, memory','v6/sprefa-store/PERF-REPORT.md')
