add(S,'v6/labs/exec_shootout/intern_bench/run.sh','v6/labs/exec_shootout/intern_bench','bash run.sh','TEXT/integer keys, pair/pair-flat/col4, exact integer twin','Recorded SQLite integer insertion 1.7–2.0× faster; interning 0.06–4.2%','Interning and representation','v6/labs/exec_shootout/intern_bench/REPORT-INTERN.md')
