for script,kind in [('17_sqlite_trigger_capabilities.py','SQLite trigger capabilities'),('20_sqlite_template.test.py','SQL template correctness'),('25_sqlite_ivm.test.py','Python public IVM correctness')]:
 add(S,'v6/labs/exec_shootout/postgres_pglite_ivm/'+script,'v6/labs/exec_shootout/postgres_pglite_ivm','python3 '+script,'Cases defined in '+script,'Assertions and probe output; not rerun',kind)
for recipe in ['runtime-shootout-smoke','runtime-shootout']:
 add(S,'v7/labs/18_runtime_shootout/4_run.sh','v7','just '+recipe,'SBCL/SWI/Racket and generated runtime chain/ring closure','JSONL; full run writes 5_RESULTS.md; count oracle','Logic runtime comparison','v7/labs/18_runtime_shootout/5_RESULTS.md')
