add(S,'v6/labs/exec_shootout/tick_bench/run.sh','v6/labs/exec_shootout/tick_bench','bash run.sh --engine ../mono/target/release/mono --input /tmp/sprefa-shootout/chain_10000.in --ticks 100 --warmups 1 --passes 3 --work /tmp/sprefa-tick-bench --label mono-chain-10000 --output /tmp/sprefa-tick-bench.tsv','100 deterministic graph updates, one warmup and three measured passes','Recorded mono chain median 55.514 ms; requires built mono and generated input','Retraction child-process timing','v6/labs/exec_shootout/tick_bench/TICKS.md')
# Research-only labs and older probes remain visible even when their original external source checkout is gone.
covered={r['source'] for r in rows if r['repo']==S+'@main'}
for base in ['v7/labs','v6/labs','v6/prolog/labs','v6/tsv2/labs']:
 for d in sorted((roots[S]/base).iterdir()):
  if not d.is_dir() or d.name=='exec_shootout':continue
  rel=str(d.relative_to(roots[S]))
  if any(x.startswith(rel+'/') or x==rel for x in covered):continue
  reports=sorted(d.glob('*RESULTS.md')) or sorted(d.glob('*REPORT*.md')) or sorted(d.glob('*RESEARCH*.md')) or sorted(d.glob('*.md'))
  if reports:
   report=reports[0]; rr=str(report.relative_to(roots[S]))
   add(S,rel,rel,'cat '+shlex.quote(report.name),'Report inspection; original probes may need external checkouts','Recorded findings in report; not rerun',d.name,receipt=rr)
  else:
   add(S,rel,rel,'git ls-files .','Source inventory; no standalone invocation verified','Probe sources; execution prerequisites unverified',d.name)
# Complete file inventory, including subsidiary probes and salvage copies.
files=[]
for repo,root in roots.items():
 for f in subprocess.check_output(['git','ls-files'],cwd=root,text=True).splitlines():
  if ('/labs/' in '/'+f or '/bench/' in '/'+f or '/benches/' in '/'+f or 'bench-cli/' in f or re.search(r'(?:bench|perf)',Path(f).name)) and not any(x in f for x in ['/results/','/target/','node_modules/','chat_log/','plans/','docs/','vendor/']):
   files.append({'repo':repo+'@main','path':f})
out=roots[Q]/'plans/costs/0_benchmark_inventory.md'
rows.sort(key=lambda r:(r['timestamp'],r['repo'],r['command']))
lines=['# Benchmarks and labs','', 'Main checkouts: `sprefa` at `3239a7c7c`; `sqlite_ivm` integration on main. Ages calculated when this inventory was generated. Receipt age is its last committed update, not a verified execution timestamp.','', '| Repo | Command | Tests / workload | Outputs | Last updated | Problem class |','|---|---|---|---|---|---|']
for r in rows:
 vals=[r['repo'],'`'+r['command']+'`',r['tests'],r['output'],r['updated'],r['class']]
 lines.append('| '+' | '.join(v.replace('|','\\|').replace('\n',' ') for v in vals)+' |')
lines += ['', 'Historical competitive plugin at `e2052d5ae` is absent from sprefa main. Its unchanged fixture generator and DD consumer are recovered in sqlite_ivm/bench/crossover. Historical 12000/1000/200: counted SQLite 21.121 ms, pg_ivm 21.311 ms, volatile DD 1.118 ms. Current replay: SQLite 91.396 ms, DD 1.091 ms. The historical performance target remains unmet.', '', 'Subsidiary source files and archived salvage probes: [1_benchmark_sources.json](1_benchmark_sources.json).']
out.write_text('\n'.join(lines)+'\n')
(roots[Q]/'plans/costs/1_benchmark_sources.json').write_text(json.dumps(files,indent=2)+'\n')

print(len(rows),'rows;',len(files),'source files')
